import logging
import requests
import re
from urllib3.exceptions import InsecureRequestWarning
from urllib.parse import urljoin
from taf.rfrl.utilities.settings import KRK_VRF_USER, KRK_VRF_PASSWORD, OMNIA_API_URL

requests.packages.urllib3.disable_warnings(category=InsecureRequestWarning)


class OmniaApi(object):
    BASE_API_URL = OMNIA_API_URL
    USER = KRK_VRF_USER
    PASSWORD = KRK_VRF_PASSWORD
    OLD_PASSWORD = 'T@F2qrk!'
    TL_LINK_TEMPLATE = 'https://omnia.krk-lab.nsn-rdnet.net/TestlineManagerService/?name={tl_name}&name__type=='

    def __init__(self):
        self.session = requests.Session()
        self.session.verify = False
        self.session.headers.update({'ContentType': 'application/json'})
        self.token = None

    def login(self):
        url_path = self._build_url('AuthorizationService/login/')
        for passwd in [OmniaApi.PASSWORD, OmniaApi.OLD_PASSWORD]:
            data = {'username': OmniaApi.USER, 'password': passwd}
            response = self.session.post(url=url_path, json=data, timeout=10)
            if response.status_code != 200:
                logging.debug(f"Login failed with status code {response.status_code}: {response.text}")
                continue
            results = response.json()
            if 'token' in results:
                self.token = results['token']
                self.session.headers.update({'Authorization': 'JWT {}'.format(self.token)})
                return
        raise Exception("Omnia login failed for user {}".format(OmniaApi.USER))

    def get_testline_data(self, params=None):
        url_path = self._build_url('TestlineManagerService/', params=params)
        response = self.session.get(url=url_path)
        results = response.json()
        return results['results']

    def _build_url(self, end_point, params=None):
        url_path = urljoin(OmniaApi.BASE_API_URL, end_point)
        if params:
            string_params = '&'.join(params)
            url_path = '{}?{}'.format(url_path, string_params)
        logging.debug("URL: {}".format(url_path))
        return url_path


def get_link_to_omnia_testline(testline):
    """
    Get link to testline in OMNIA
    :param testline: testline name
    :return: str - link to testline in OMNIA
    """
    tl_link = OmniaApi.TL_LINK_TEMPLATE.format(tl_name=testline)
    return tl_link


def get_testline_details(testline):
    """
    Get testline details from Omnia
    :param testline: testline name
    :return dict: testline details
    """
    params = [
        'name={}'.format(testline),
        'name__type=in'
    ]
    tl_omnia = OmniaApi()
    tl_omnia.login()
    return tl_omnia.get_testline_data(params=params)[0]


def get_testline_owner_info_from_omnia(testline):
    """
    Get testline owner info from OMNIA.

    :param testline: testline name
    :return: dict - testline details
    """
    tl_details = get_testline_details(testline)
    owner_details = {
        'owner_email': tl_details['owner_email'],
        'owner_name': tl_details['owner_name'],
        'team_name': tl_details['owner_squad_group'],
        'link': get_link_to_omnia_testline(testline),
    }
    return owner_details


def get_scout_bts_names_for_testline(testline):
    """
    Get scout BTS names for given testline
    :param testline: testline name
    :return list: list of scout BTS names
    """
    re_scout_bts_name = re.compile(r'testlines/(?P<TL_NAME>.*?)/')
    tl_details = get_testline_details(testline)
    scout_links = tl_details.get('scout_link')
    scout_bts_names = []
    if scout_links:
        for scout_link in scout_links.split(','):
            match = re_scout_bts_name.search(scout_link)
            if match:
                scout_bts_names.append(match.group('TL_NAME'))
        scout_bts_names.sort()

    return scout_bts_names
